 string ManagedFolder(string relative,bool metadata=false,bool create=true){if(String.IsNullOrWhiteSpace(managedPath))throw new InvalidOperationException("Choose a library home first.");relative=(relative??"").Replace('\\','/').Trim('/');if(!metadata&&relative.StartsWith(".jago-library",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("That folder is reserved for the library catalog.");var parts=relative.Length==0?new string[0]:relative.Split('/');if(parts.Length>5)throw new InvalidOperationException("Use at most five nested folder levels.");string path=managedPath;if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new InvalidOperationException("Choose a regular library folder rather than a junction.");foreach(var part in parts){if(part=="."||part==".."||part.Length==0||part.Length>120||part.IndexOfAny(Path.GetInvalidFileNameChars())>=0||part.TrimEnd(' ','.')!=part||System.Text.RegularExpressions.Regex.IsMatch(part,@"^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(\.|$)",System.Text.RegularExpressions.RegexOptions.IgnoreCase))throw new InvalidOperationException("Use ordinary folder names without reserved names or traversal.");path=Path.Combine(path,part);if(Directory.Exists(path)&&(File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new InvalidOperationException("Library subfolders cannot be junctions.");if(create)Directory.CreateDirectory(path);}string full=Path.GetFullPath(path),root=Path.GetFullPath(managedPath).TrimEnd(Path.DirectorySeparatorChar);if(full!=root&&!full.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Folder is outside the library.");return full;}
 string Kind(string file){var ext=Path.GetExtension(file).ToLowerInvariant();return new[]{".png",".jpg",".jpeg",".webp",".gif",".bmp",".svg"}.Contains(ext)?"image":new[]{".ttf",".otf",".woff",".woff2"}.Contains(ext)?"font":new[]{".wav",".mp3",".ogg",".m4a",".flac"}.Contains(ext)?"audio":new[]{".mp4",".webm",".mov"}.Contains(ext)?"video":ext==".pdf"?"pdf":new[]{".psd",".psb",".ai",".eps",".afdesign",".afphoto",".afpub",".af",".affinity",".aftemplate",".afassets",".blend",".fbx",".obj",".glb",".gltf",".aseprite",".procreate",".abr",".jagomaterial",".jagoworld",".jagomusic",".dxf",".stl",".heic",".tif",".tiff",".exr",".kra",".ora"}.Contains(ext)?"special":"special";}
 string RootId(string path){if(managedPath!=null&&Path.GetFullPath(path).TrimEnd(Path.DirectorySeparatorChar).Equals(managedPath.TrimEnd(Path.DirectorySeparatorChar),StringComparison.OrdinalIgnoreCase))return managedId;using(var sha=SHA256.Create())return "r"+BitConverter.ToString(sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(Path.GetFullPath(path).ToLowerInvariant()))).Replace("-","").Substring(0,12).ToLowerInvariant();}
