 async Task IndexManaged(string type){var assets=new List<object>();var folders=new List<string>();await Task.Run(()=>{var pending=new Stack<Tuple<string,int>>();pending.Push(Tuple.Create(managedPath,0));while(pending.Count>0&&assets.Count<2000){var node=pending.Pop();try{foreach(var file in Directory.GetFiles(node.Item1)){var a=ManagedAsset(file,managedPath,managedId);if(a!=null)assets.Add(a);if(assets.Count>=2000)break;}if(node.Item2<5)foreach(var dir in Directory.GetDirectories(node.Item1)){if(Path.GetFileName(dir)==".jago-library"||(File.GetAttributes(dir)&FileAttributes.ReparsePoint)!=0)continue;if(folders.Count<200)folders.Add(dir.Substring(managedPath.TrimEnd(Path.DirectorySeparatorChar).Length+1).Replace('\\','/'));pending.Push(Tuple.Create(dir,node.Item2+1));}}catch(UnauthorizedAccessException){}catch(IOException){}}});browser.CoreWebView2.SetVirtualHostNameToFolderMapping(managedId+".jagolibrary.example",managedPath,CoreWebView2HostResourceAccessKind.Allow);string catalog=Path.Combine(managedPath,".jago-library","catalog.jagolibrary"),project=null;if(type=="library-home"&&File.Exists(catalog)&&new FileInfo(catalog).Length<45000000)project=File.ReadAllText(catalog);ManagedPost(new{type=type,root=new{id=managedId,name="Library home",path=managedPath,managed=true},assets=assets,folders=folders.OrderBy(x=>x).ToArray(),project=project,capped=assets.Count>=2000});}
 async Task HandleManaged(Dictionary<string,object> message){string type=Convert.ToString(message["type"]);if(type=="library-home"||type=="test-library-home"||type=="restore-library-home"){string path=null;if(type=="test-library-home"){if(Program.Test==null)return;path=Path.Combine(Program.Test,"ManagedLibrary");Directory.CreateDirectory(path);}else if(type=="restore-library-home"){path=Convert.ToString(message["path"]);string marker=Path.Combine(path,".jago-library","library-id.txt");if(!Directory.Exists(path)||!File.Exists(marker)||File.ReadAllText(marker)!=Convert.ToString(message["id"]))return;}else path=ModernFolder.Pick(Handle,"Choose or create a collected library home");if(path==null)return;managedPath=Path.GetFullPath(path);string meta=ManagedFolder(".jago-library",true),idFile=Path.Combine(meta,"library-id.txt");managedId=File.Exists(idFile)?File.ReadAllText(idFile):"r"+Guid.NewGuid().ToString("N").Substring(0,12);if(!System.Text.RegularExpressions.Regex.IsMatch(managedId,@"^r[a-f0-9]{12}$"))throw new InvalidDataException("Library identifier is not valid.");if(!File.Exists(idFile))File.WriteAllText(idFile,managedId);await IndexManaged(type=="restore-library-home"?"library-index":"library-home");}
 else if(type=="library-subfolder"){ManagedFolder(Convert.ToString(message["folder"]));await IndexManaged("library-index");}
 else if(type=="collect-cancel")cancelCollect=true;
 else if(type=="collect-assets"){string destination=ManagedFolder(Convert.ToString(message["folder"]));var ids=message["ids"] as System.Collections.ArrayList;var errors=new List<string>();int copied=0;var copies=new List<object>();cancelCollect=false;if(ids==null||ids.Count>2000)throw new InvalidOperationException("Collect at most 2,000 files per operation.");foreach(var key in ids){if(cancelCollect)break;string file;if(!assetPaths.TryGetValue(Convert.ToString(key),out file)||!File.Exists(file)){errors.Add("Original file unavailable");continue;}if((File.GetAttributes(file)&FileAttributes.ReparsePoint)!=0){errors.Add("Skipped linked file");continue;}string folder=destination;if(message.ContainsKey("keepFolders")&&Convert.ToBoolean(message["keepFolders"])){string keyText=Convert.ToString(key),relative=keyText.Substring(keyText.IndexOf(':')+1);string parent=Path.GetDirectoryName(relative.Replace('/',Path.DirectorySeparatorChar));if(!String.IsNullOrEmpty(parent))folder=ManagedFolder(String.Join("/",new[]{Convert.ToString(message["folder"]),parent.Replace('\\','/')}.Where(x=>!String.IsNullOrEmpty(x))));}string target=Path.Combine(folder,Path.GetFileName(file));if(Path.GetFullPath(file).Equals(Path.GetFullPath(target),StringComparison.OrdinalIgnoreCase)){copied++;copies.Add(new{from=Convert.ToString(key),to=managedId+":"+target.Substring(managedPath.TrimEnd(Path.DirectorySeparatorChar).Length+1).Replace('\\','/')});continue;}if(File.Exists(target)&&new FileInfo(target).Length==new FileInfo(file).Length&&await Task.Run(()=>HomeHash(file)==HomeHash(target))){copied++;copies.Add(new{from=Convert.ToString(key),to=managedId+":"+target.Substring(managedPath.TrimEnd(Path.DirectorySeparatorChar).Length+1).Replace('\\','/')});continue;}for(int n=2;File.Exists(target);n++)target=Path.Combine(folder,Path.GetFileNameWithoutExtension(file)+" ("+n+")"+Path.GetExtension(file));try{await Task.Run(()=>{string temp=target+".jago-copy-"+Guid.NewGuid().ToString("N");try{File.Copy(file,temp,false);if(HomeHash(file)!=HomeHash(temp))throw new IOException("Copy verification failed; original kept.");File.Move(temp,target);}finally{if(File.Exists(temp))File.Delete(temp);}});copied++;copies.Add(new{from=Convert.ToString(key),to=managedId+":"+target.Substring(managedPath.TrimEnd(Path.DirectorySeparatorChar).Length+1).Replace('\\','/')});}catch(Exception e){errors.Add(Path.GetFileName(file)+": "+e.Message);}ManagedPost(new{type="collect-progress",done=copied,total=ids.Count});}await IndexManaged("library-index");ManagedPost(new{type="collect-complete",copied=copied,cancelled=cancelCollect,copies=copies,errors=errors.Take(5).ToArray()});}
 else if(type=="add-files"||type=="test-add-files"){var files=new List<string>();if(type=="test-add-files"){if(Program.Test==null)return;files.AddRange(Directory.GetFiles(Path.Combine(Program.Test,"Fixture")).Take(2));}else using(var d=new OpenFileDialog()){d.Title="Add creative files to your library";d.Multiselect=true;d.Filter="All creative files|*.*";if(d.ShowDialog(this)==DialogResult.OK)files.AddRange(d.FileNames);}var roots=new List<object>();var assets=new List<object>();foreach(var file in files){string root=Path.GetDirectoryName(file),rid=RootId(root);browser.CoreWebView2.SetVirtualHostNameToFolderMapping(rid+".jagolibrary.example",root,CoreWebView2HostResourceAccessKind.Allow);roots.Add(new{id=rid,name=Path.GetFileName(root),path=root,filesOnly=true});var a=ManagedAsset(file,root,rid);if(a!=null)assets.Add(a);}ManagedPost(new{type="files-added",roots=roots,assets=assets});}
 else if(type=="save-library"){string data=Convert.ToString(message["project"]);if(data.Length>45000000)throw new InvalidOperationException("Catalog exceeds 45 MB.");string meta=ManagedFolder(".jago-library",true),file=Path.Combine(meta,"catalog.jagolibrary"),temp=file+".new";File.WriteAllText(temp,data);if(File.Exists(file)){File.Copy(file,file+".previous",true);File.Replace(temp,file,null);}else File.Move(temp,file);ManagedPost(new{type="library-saved"});}
 else if(type=="export-library"){if(managedPath==null)throw new InvalidOperationException("Choose a library home first.");string destination=null;if(Program.Test!=null)destination=Path.Combine(Program.Test,"Portable-library.zip");else using(var d=new SaveFileDialog()){d.Title="Export collected library";d.Filter="ZIP archive|*.zip";d.DefaultExt="zip";d.AddExtension=true;d.FileName="Jago-Library.zip";if(d.ShowDialog(this)==DialogResult.OK)destination=d.FileName;}if(destination==null)return;if(Path.GetExtension(destination).ToLowerInvariant()!=".zip")throw new InvalidOperationException("Use a .zip filename.");var selected=assetPaths.Where(p=>p.Key.StartsWith(managedId+":",StringComparison.Ordinal)).Select(p=>p.Value).Distinct().Where(f=>File.Exists(f)&&f.StartsWith(managedPath.TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)).ToArray();if(selected.Any(f=>Path.GetFullPath(f).Equals(Path.GetFullPath(destination),StringComparison.OrdinalIgnoreCase)))throw new InvalidOperationException("Export to a new ZIP outside the collected source files.");await Task.Run(()=>{using(var output=File.Create(destination))using(var zip=new ZipArchive(output,ZipArchiveMode.Create)){foreach(var file in selected){if((File.GetAttributes(file)&FileAttributes.ReparsePoint)!=0)continue;string relative=file.Substring(managedPath.TrimEnd(Path.DirectorySeparatorChar).Length+1).Replace('\\','/');zip.CreateEntryFromFile(file,"Jago-Library/"+relative,CompressionLevel.Optimal);}foreach(var name in new[]{"library-id.txt","catalog.jagolibrary"}){string file=Path.Combine(managedPath,".jago-library",name);if(File.Exists(file)){if(name=="catalog.jagolibrary"){var portable=ProjectSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(file));portable.Remove("exportHistory");using(var writer=new StreamWriter(zip.CreateEntry("Jago-Library/.jago-library/"+name).Open()))writer.Write(ProjectSerializer().Serialize(portable));}else zip.CreateEntryFromFile(file,"Jago-Library/.jago-library/"+name,CompressionLevel.Optimal);}}}});RegisterProjectOutput(destination);ManagedPost(new{type="library-exported",files=selected.Length,path=destination,bytes=new FileInfo(destination).Length});}
 }
